import {confirmConnection} from './connection-message.mjs';
const providers=new Map();let selected=null,account=null,pending=false,generation=0,unbind=()=>{};
const button=document.querySelector('#wallet-connect');
const walletControl=document.createElement('div');walletControl.className='connected-wallet-control';button.before(walletControl);walletControl.append(button);
const dropdown=document.createElement('div');dropdown.id='connected-wallet-actions';dropdown.className='connected-wallet-actions';dropdown.hidden=true;dropdown.setAttribute('aria-label','Wallet actions');dropdown.innerHTML='<span class="connected-wallet-name"></span><a href="#inventory">Inventory <span aria-hidden="true">↗</span></a><button type="button" data-copy>Copy address</button><button type="button" data-menu-disconnect>Disconnect</button><span class="wallet-copy-status" role="status" aria-live="polite"></span>';walletControl.append(dropdown);
function closeDropdown(focus=false){dropdown.hidden=true;button.setAttribute('aria-expanded','false');if(focus)button.focus();}
const dialog=document.createElement('dialog');dialog.className='wallet-picker';dialog.setAttribute('aria-labelledby','wallet-picker-title');dialog.innerHTML='<div class="wallet-dialog-head"><h2 id="wallet-picker-title">CONNECT WALLET</h2><button type="button" data-close aria-label="Close wallet selection">×</button></div><p class="wallet-intro">Choose your EVM wallet, then approve the readable connection message. No transaction or token approval is requested.</p><div data-wallets></div><p class="wallet-message" role="status" aria-live="polite"></p><div class="wallet-dialog-footer"><button type="button" data-refresh>Refresh wallets</button><button type="button" data-disconnect hidden>Disconnect</button></div>';
document.body.append(dialog);
const address=v=>typeof v==='string'&&/^0x[0-9a-fA-F]{40}$/.test(v);
function update(){closeDropdown();button.textContent=account?account.slice(0,6)+'…'+account.slice(-4)+' ▾':'Connect wallet';button.setAttribute('aria-label',account?'Manage connected wallet '+account:'Connect wallet');button.setAttribute('aria-controls',account?dropdown.id:dialog.id);dropdown.querySelector('.connected-wallet-name').textContent=selected?.name||'';dropdown.querySelector('.wallet-copy-status').textContent='';dialog.querySelector('[data-disconnect]').hidden=!account;window.dispatchEvent(new CustomEvent('fillout:wallet',{detail:{account,wallet:selected?.name||null}}));}
function add(provider,name,id,icon){if(!provider||typeof provider.request!=='function')return;const existing=[...providers.values()].find(x=>x.provider===provider);if(existing){if(existing.legacy&&!id.startsWith('legacy')){providers.delete(existing.id);}else return;}providers.set(id,{id,provider,name:String(name||'EVM wallet').slice(0,60),legacy:id.startsWith('legacy'),icon:typeof icon==='string'&&/^data:image\/(png|webp|svg\+xml|jpeg);/i.test(icon)?icon:null});if(dialog.open)list();}
window.addEventListener('eip6963:announceProvider',e=>{try{const d=e.detail;if(!d?.info||typeof d.info.uuid!=='string')return;add(d.provider,d.info.name,'eip:'+d.info.uuid,d.info.icon);}catch{}});
function discover(){window.dispatchEvent(new Event('eip6963:requestProvider'));const roots=[window.okxwallet,window.bitkeep?.ethereum,window.bitget?.ethereum,...(Array.isArray(window.ethereum?.providers)?window.ethereum.providers:[]),window.ethereum];roots.forEach((p,i)=>{if(!p)return;const name=p===window.okxwallet||p.isOkxWallet||p.isOKExWallet?'OKX Wallet':p.isBitKeep||p.isBitget||p===window.bitkeep?.ethereum||p===window.bitget?.ethereum?'Bitget Wallet':p.isMetaMask?'MetaMask':'Browser EVM wallet';add(p,name,'legacy:'+i);});list();}
function walletLogo(name,provided){const lower=name.toLowerCase();const src=provided||(lower.includes('metamask')?'wallet-metamask.svg':lower.includes('okx')?'wallet-okx.png':lower.includes('bitget')||lower.includes('bitkeep')?'wallet-bitget.ico':null);if(!src){const fallback=document.createElement('span');fallback.className='wallet-logo-fallback';fallback.textContent=name.slice(0,1).toUpperCase();fallback.setAttribute('aria-hidden','true');return fallback;}const img=document.createElement('img');img.className='wallet-logo';img.src=src;img.alt='';img.width=32;img.height=32;img.onerror=()=>{const fallback=document.createElement('span');fallback.className='wallet-logo-fallback';fallback.textContent=name.slice(0,1).toUpperCase();fallback.setAttribute('aria-hidden','true');img.replaceWith(fallback);};return img;}
function list(){const host=dialog.querySelector('[data-wallets]');host.replaceChildren();const entries=[...providers.values()];for(const label of ['MetaMask','OKX Wallet','Bitget Wallet']){if(!entries.some(x=>x.name.toLowerCase().includes(label.split(' ')[0].toLowerCase()))){const row=document.createElement('div');row.className='wallet-unavailable';const name=document.createElement('span');name.textContent=label;name.prepend(walletLogo(label));const note=document.createElement('small');note.textContent='Not detected';row.append(name,note);host.append(row);}}
for(const item of entries){const row=document.createElement('button');row.type='button';row.className='wallet-option';row.disabled=pending;const name=document.createElement('span');name.textContent=item.name;name.prepend(walletLogo(item.name,item.icon));const mark=document.createElement('small');mark.textContent=selected?.provider===item.provider&&account?'Connected':'Connect →';row.append(name,mark);row.onclick=()=>connect(item);host.prepend(row);}if(!entries.length)message('No wallet detected in this browser. Open this page in the browser where your wallet extension is installed.');}
function message(value){dialog.querySelector('.wallet-message').textContent=value;}
function clear(){generation++;unbind();unbind=()=>{};selected=null;account=null;update();}
function bind(item){const p=item.provider;const changed=accounts=>{if(selected!==item)return;const next=Array.isArray(accounts)&&address(accounts[0])?accounts[0]:null;if(!next||next.toLowerCase()!==account?.toLowerCase()){clear();message('Account changed. Connect again to confirm this wallet.');list();}};const disconnected=()=>{if(selected===item){clear();message('Wallet disconnected.');list();}};if(typeof p.on==='function'){p.on('accountsChanged',changed);p.on('disconnect',disconnected);}unbind=()=>{p.removeListener?.('accountsChanged',changed);p.removeListener?.('disconnect',disconnected);};}
async function connect(item){if(pending)return;pending=true;const ticket=++generation;message('Continue in '+item.name+'…');list();try{const accounts=await item.provider.request({method:'eth_requestAccounts'});if(ticket!==generation)return;if(!Array.isArray(accounts)||!address(accounts[0]))throw Error('No account was provided by the wallet.');const current=await item.provider.request({method:'eth_accounts'});if(ticket!==generation)return;if(!Array.isArray(current)||!address(current[0])||current[0].toLowerCase()!==accounts[0].toLowerCase())throw Error('Wallet account changed. Please connect again.');message('Confirm the FillOut connection message in '+item.name+'…');await confirmConnection(item.provider,current[0],()=>ticket===generation);if(ticket!==generation)return;unbind();selected=item;account=current[0];bind(item);update();message('Connected to '+item.name+'. Connection message verified. No transaction requested.');dialog.close();}catch(e){if(ticket===generation)message(e?.code===4001?'Connection cancelled.':e?.code===-32002?'A connection request is already open in your wallet.':e?.message==='No account was provided by the wallet.'||e?.message==='Wallet account changed. Please connect again.'?e.message:'Could not connect. Check your wallet and try again.');}finally{pending=false;list();}}
dialog.id='wallet-selection-dialog';
button.onclick=()=>{if(account){dropdown.hidden=!dropdown.hidden;button.setAttribute('aria-expanded',String(!dropdown.hidden));return;}message('');dialog.showModal();discover();};dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('[data-refresh]').onclick=()=>{message('');discover();};dialog.querySelector('[data-disconnect]').onclick=()=>{clear();message('Disconnected from this site. Wallet extension permissions can be managed in your wallet.');list();};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
dropdown.querySelector('a').onclick=()=>closeDropdown();dropdown.querySelector('[data-menu-disconnect]').onclick=()=>{clear();button.focus();};dropdown.querySelector('[data-copy]').onclick=async()=>{const copiedAccount=account;if(!copiedAccount)return;try{await navigator.clipboard.writeText(copiedAccount);if(account===copiedAccount)dropdown.querySelector('.wallet-copy-status').textContent='Address copied';}catch{dropdown.querySelector('.wallet-copy-status').textContent='Copy unavailable. Address: '+copiedAccount;}};
document.addEventListener('click',e=>{if(!walletControl.contains(e.target))closeDropdown();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dropdown.hidden){e.preventDefault();closeDropdown(true);}});walletControl.addEventListener('focusout',e=>{if(!walletControl.contains(e.relatedTarget))closeDropdown();});window.addEventListener('hashchange',()=>closeDropdown());
update();
